WITH flattened_attrs AS (SELECT id, coupon_codes, ship_to, attributes, SIZE(attributes) AS num_attributes, attributes['gift'] AS gift, SIZE(items) AS num_items, COALESCE(attributes['utm_source'], 'unknown') AS utm_source_or_default, ship_to.country AS ship_country FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'WELCOME5')) SELECT *, SUM(num_attributes) OVER (PARTITION BY ship_country ORDER BY num_items, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_num_attributes, AVG(num_attributes) OVER (ORDER BY num_attributes, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS num_attributes_avg_2_prior FROM flattened_attrs
